  return (
    <nav className="sticky top-0 z-40 w-full glass border-b border-white/20 dark:border-white/5">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between h-20 items-center relative">

          <div className="flex items-center gap-4 flex-shrink-0">
             {showBackButton && (
                 <button 
                    onClick={() => navigate(-1)} 
                    className="md:hidden w-10 h-10 flex items-center justify-center rounded-full bg-white/80 dark:bg-darkSurface/80 hover:bg-white dark:hover:bg-darkSurface border border-gray-100 dark:border-gray-800 text-gray-700 dark:text-gray-300 transition-all shadow-sm active:scale-95"
                 >
                     <i className="fa-solid fa-arrow-left text-sm"></i>
                 </button>
             )}

             <div className="flex items-center gap-3 cursor-pointer group" onClick={() => navigate('/')}>
                <img 
