                        <span className={`text-[10px] font-bold text-center w-full uppercase ${isSelected ? 'text-primary' : 'text-gray-500 dark:text-gray-400'}`}>
                            {cat.name}
                        </span>
                    </div>
                );
            })}
        </div>
      </div>

      {/* Trending Now - Automatic Seamless Infinite Scroller */}
      <div className="pl-4">
        <div className="flex justify-between items-center mb-3 pr-4">
            <h3 className="font-display font-bold text-gray-900 dark:text-white text-sm uppercase tracking-widest flex items-center gap-2">
                <i className="fa-solid fa-fire text-orange-500"></i>
                Trending Now
            </h3>
