import React, { createContext, useContext, useState, useEffect, useRef } from 'react';
import { User, Product, Vendor, Order, CartItem, Courier, Role, OrderStatus, Notification, NotificationPreferences, VendorNotificationPreferences } from './types';
import { supabase } from './supabaseClient';
import { ToastMessage } from './components/UI';
import { INITIAL_LOCATION_CACHE } from './constants';

type ThemeMode = 'light' | 'dark' | 'system';

interface AppContextType {
  currentUser: User | null;
  currentRole: Role;
  products: Product[];
  vendors: Vendor[];
  orders: Order[];
  cart: CartItem[];
  couriers: Courier[];
  users: User[];
  notifications: Notification[];
  unreadNotificationCount: number;
  notificationPreferences: NotificationPreferences | null;
  vendorPreferences: VendorNotificationPreferences | null;
  isLoading: boolean;
  isDataLoading: boolean;
  connectionError: boolean;
  favorites: string[];
  toast: ToastMessage | null;
  theme: ThemeMode;

  login: (email: string, password: string) => Promise<{success: boolean, role?: Role, error?: string}>;
  signup: (email: string, password: string, fullName: string, role: Role, phoneNumber?: string) => Promise<{success: boolean, error?: string, user?: any}>;
  logout: () => Promise<void>;
  resetPassword: (email: string) => Promise<{success: boolean, error?: string}>;
  updatePassword: (password: string) => Promise<{success: boolean, error?: string}>;
  switchRole: (role: Role) => void;
  updateTheme: (theme: ThemeMode) => void;

  updateProfile: (data: Partial<User>) => Promise<{ success: boolean }>;
  submitContactMessage: (name: string, email: string, message: string) => Promise<{ success: boolean }>;
  requestPayout: (amount: number, method: string) => Promise<{ success: boolean }>;

  uploadFile: (file: File, folder: string) => Promise<string | null>;
  registerCourier: (data: Partial<Courier> & { phoneNumber?: string }, explicitUserId?: string) => Promise<{ success: boolean }>;
  registerVendor: (data: { storeName: string; storeDescription: string; location: string; contactPhone: string; storeAvatarUrl?: string }) => Promise<{ success: boolean }>;
  refreshData: () => Promise<void>;

  addProduct: (product: any) => Promise<boolean>;
  updateProduct: (id: string, data: Partial<Product>) => Promise<void>;
  updateProductStatus: (id: string, status: Product['status']) => Promise<void>;
  deleteProduct: (id: string) => Promise<void>;

  addToCart: (product: Product, quantity?: number) => void;
  updateCartQuantity: (productId: string, quantity: number) => void;
  removeFromCart: (productId: string) => void;
  clearCart: () => void;
  placeOrder: (deliveryOption: 'delivery' | 'pickup', fee?: number) => Promise<void>;
  updateOrderStatus: (orderId: string, status: OrderStatus) => Promise<void>;
  assignDelivery: (orderId: string) => Promise<void>;
  toggleFavorite: (productId: string) => void;

  // Notification Actions
  markNotificationAsRead: (id: string) => Promise<void>;
  markAllNotificationsRead: () => Promise<void>;
  deleteNotification: (id: string) => Promise<void>;
  updateNotificationPreferences: (prefs: Partial<NotificationPreferences>) => Promise<void>;
  updateVendorPreferences: (prefs: Partial<VendorNotificationPreferences>) => Promise<void>;
  sendBroadcast: (title: string, message: string, scope: 'global' | 'role', role?: Role) => Promise<void>;

  banUser: (userId: string, status: boolean) => Promise<void>;
  deleteUser: (userId: string) => Promise<void>;
  approveVendor: (vendorId: string, status: boolean) => Promise<void>;
  approveCourier: (id: string, userId: string, status: 'approved' | 'rejected' | 'suspended') => Promise<void>;

  toggleDriverStatus: (isOnline: boolean) => Promise<void>;
  updateDriverLocation: (lat: number, lng: number) => Promise<void>;

  showToast: (message: string, type: 'success' | 'error' | 'info') => void;
  hideToast: () => void;
  requestNotificationPermission: () => Promise<boolean>;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

const safeSetItem = (key: string, value: string) => {
    try {
        localStorage.setItem(key, value);
    } catch (e) {
        console.warn(`LocalStorage quota exceeded. Failed to save ${key}.`);
    }
};

const resolveCoordinates = (locationName: string): {lat: number, lng: number} | undefined => {
    const clean = locationName.toLowerCase().trim();
    if (INITIAL_LOCATION_CACHE[clean]) {
        return { lat: INITIAL_LOCATION_CACHE[clean][0], lng: INITIAL_LOCATION_CACHE[clean][1] };
    }
    const key = Object.keys(INITIAL_LOCATION_CACHE).find(k => clean.includes(k));
    if (key) {
        return { lat: INITIAL_LOCATION_CACHE[key][0], lng: INITIAL_LOCATION_CACHE[key][1] };
    }
    return { lat: 5.6506, lng: -0.1962 };
};

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [products, setProducts] = useState<Product[]>([]);
  const [vendors, setVendors] = useState<Vendor[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [couriers, setCouriers] = useState<Courier[]>([]);
  const [users, setUsers] = useState<User[]>([]);

  // Notification state
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [notificationPreferences, setNotificationPreferences] = useState<NotificationPreferences | null>(null);
  const [vendorPreferences, setVendorPreferences] = useState<VendorNotificationPreferences | null>(null);

  const [currentRole, setCurrentRole] = useState<Role>(() => {
      try { return (localStorage.getItem('lynqed_role') as Role) || 'guest'; } catch { return 'guest'; }
  });

  const [theme, setTheme] = useState<ThemeMode>(() => {
      try { return (localStorage.getItem('lynqed_theme_last') as ThemeMode) || 'system'; } catch { return 'system'; }
  });

  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [isDataLoading, setIsDataLoading] = useState<boolean>(true);
  const [connectionError, setConnectionError] = useState<boolean>(false);
  const [toast, setToast] = useState<ToastMessage | null>(null);

  const [cart, setCart] = useState<CartItem[]>(() => {
      try { return JSON.parse(localStorage.getItem('lynqed_cart') || '[]'); } catch { return []; }
  });
  const [favorites, setFavorites] = useState<string[]>(() => {
      try { return JSON.parse(localStorage.getItem('lynqed_favs') || '[]'); } catch { return []; }
  });

  const unreadNotificationCount = notifications.filter(n => !n.isRead).length;

  useEffect(() => { safeSetItem('lynqed_cart', JSON.stringify(cart)); }, [cart]);
  useEffect(() => { safeSetItem('lynqed_favs', JSON.stringify(favorites)); }, [favorites]);

  useEffect(() => { 
      if (currentRole !== 'guest') {
          safeSetItem('lynqed_role', currentRole); 
      }
  }, [currentRole]);

  useEffect(() => {
    if (currentUser) {
        const userTheme = localStorage.getItem(`lynqed_theme_${currentUser.id}`) as ThemeMode;
        if (userTheme) setTheme(userTheme);
    } else {
        const guestTheme = (localStorage.getItem('lynqed_theme_last') as ThemeMode) || 'system';
        setTheme(guestTheme);
    }
  }, [currentUser]);

  useEffect(() => {
    const applyTheme = (mode: ThemeMode) => {
        const root = window.document.documentElement;
        let isDark = mode === 'dark';
        if (mode === 'system') {
            isDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
        }

        if (isDark) root.classList.add('dark');
        else root.classList.remove('dark');

        safeSetItem('lynqed_theme_last', mode);
        if (currentUser) safeSetItem(`lynqed_theme_${currentUser.id}`, mode);
    };

    applyTheme(theme);

    if (theme === 'system') {
        const mediaQuery = window.matchMedia('(prefers-color-scheme: dark)');
        const handler = () => applyTheme('system');
        mediaQuery.addEventListener('change', handler);
        return () => mediaQuery.removeEventListener('change', handler);
    }
  }, [theme, currentUser]);

  const updateTheme = (newTheme: ThemeMode) => setTheme(newTheme);

  const vendorsRef = useRef(vendors);
  const currentUserRef = useRef(currentUser);
  const currentRoleRef = useRef(currentRole);

  useEffect(() => { vendorsRef.current = vendors; }, [vendors]);
  useEffect(() => { currentUserRef.current = currentUser; }, [currentUser]);
  useEffect(() => { currentRoleRef.current = currentRole; }, [currentRole]);

  useEffect(() => {
    initApp();
    try {
        const productSub = supabase.channel('public:products').on('postgres_changes', { event: '*', schema: 'public', table: 'products' }, () => fetchData()).subscribe();
        const orderSub = supabase.channel('public:orders').on('postgres_changes', { event: '*', schema: 'public', table: 'orders' }, (payload) => {
              fetchData();
          }).subscribe();

        const vendorSub = supabase.channel('public:vendors').on('postgres_changes', { event: '*', schema: 'public', table: 'vendors' }, () => fetchData()).subscribe();

        // Notifications real-time sub
        const notifSub = supabase.channel('public:notifications').on('postgres_changes', { event: '*', schema: 'public', table: 'notifications' }, () => {
             fetchNotifications();
        }).subscribe();

        return () => {
            supabase.removeChannel(productSub);
            supabase.removeChannel(orderSub);
            supabase.removeChannel(vendorSub);
            supabase.removeChannel(notifSub);
        };
    } catch (e) {
        console.error("Realtime subscription failed:", e);
    }
  }, [currentUser]); // Re-sub if user changes

  const initApp = async () => {
      try {
          await checkSession();
          await fetchData();
          setConnectionError(false);
      } catch (e: any) {
          console.error("Initialization Failed:", e);
      } finally {
          setIsLoading(false);
          setIsDataLoading(false);
      }
  };

  const checkSession = async () => {
      try {
          const { data, error } = await supabase.auth.getSession();
          if (error) throw error;
          if (data.session?.user) {
              await fetchUserProfile(data.session.user.id, data.session.user);
          } else {
              setCurrentUser(null);
              setCurrentRole('guest');
          }
      } catch (e: any) { 
          console.error("Session check error:", e);
      } 
  };

  const fetchUserProfile = async (userId: string, sessionUser?: any): Promise<User | null> => {
      try {
          const { data, error } = await supabase.from('profiles').select('*').eq('id', userId).maybeSingle();
          if (error) throw error;

          if (data) {
              if (data.isBanned) throw new Error("Account Suspended");

              const user: User = { 
                  ...data, 
                  roles: data.roles || ['buyer'],
                  avatarUrl: data.avatar_url,
                  phoneNumber: data.phone_number,
                  defaultLocation: data.address
              };

              setCurrentUser(user);

              const persistedRole = localStorage.getItem('lynqed_role') as Role;
              let finalRole: Role = 'buyer';

              if (user.roles.includes('admin')) {
                  finalRole = 'admin';
              } else if (persistedRole && user.roles.includes(persistedRole)) {
                  finalRole = persistedRole;
              } else if (user.roles.includes('vendor')) {
                  finalRole = 'vendor';
              } else if (user.roles.includes('courier')) {
                  finalRole = 'courier';
              } else if (user.roles.includes('buyer')) {
                  finalRole = 'buyer';
              }

              setCurrentRole(finalRole);
              if (finalRole !== 'guest') safeSetItem('lynqed_role', finalRole);

              fetchNotifications();
              fetchNotificationPreferences(userId);

              return user;
          } else if (sessionUser) {
              const { error: insertError } = await supabase.from('profiles').insert({
                  id: userId,
                  email: sessionUser.email,
                  name: sessionUser.user_metadata?.full_name || sessionUser.email?.split('@')[0] || 'New User',
                  roles: ['buyer']
              });
              if (!insertError) return fetchUserProfile(userId, undefined);
          }
      } catch (e: any) {
          console.error("Profile fetch error", e);
      }
      return null;
  };

  const fetchNotifications = async () => {
    if (!currentUserRef.current) return;
    try {
        const { data, error } = await supabase.from('notifications')
            .select('*')
            .or(`user_id.eq.${currentUserRef.current.id},target_scope.eq.global,target_role.eq.${currentRoleRef.current}`)
            .order('created_at', { ascending: false });

        if (error) throw error;
        if (data) {
            setNotifications(data.map(n => ({
                id: n.id,
                userId: n.user_id,
                targetRole: n.target_role,
                targetScope: n.target_scope,
                type: n.type,
                title: n.title,
                message: n.message,
                dataPayload: n.data_payload,
                priority: n.priority,
                isRead: n.is_read,
                createdAt: n.created_at
            })));
        }
    } catch (e) {
        console.error("Fetch notifications error", e);
    }
  };

  const fetchNotificationPreferences = async (userId: string) => {
      try {
          const { data: mainPrefs } = await supabase.from('notification_preferences').select('*').eq('user_id', userId).maybeSingle();
          if (mainPrefs) setNotificationPreferences({
              userId: mainPrefs.user_id,
              globalToggle: mainPrefs.global_toggle,
              // Fix: Changed in_app to inApp to match NotificationPreferences interface
              inApp: mainPrefs.in_app,
              email: mainPrefs.email,
              push: mainPrefs.push,
              orders: mainPrefs.orders,
              messages: mainPrefs.messages,
              delivery: mainPrefs.delivery,
              promotions: mainPrefs.promotions,
              systemUpdates: mainPrefs.system_updates
          });

          const { data: vPrefs } = await supabase.from('vendor_notification_preferences').select('*').eq('user_id', userId).maybeSingle();
          if (vPrefs) setVendorPreferences({
              userId: vPrefs.user_id,
              newOrders: vPrefs.new_orders,
              productApproval: vPrefs.product_approval,
              storeTips: vPrefs.store_tips,
              policyChanges: vPrefs.policy_changes
          });
      } catch (e) { console.error(e); }
  };

  const fetchData = async () => {
      try {
          const fetchSafely = async (table: string, select = '*', orderBy?: string) => {
             try {
                let query = supabase.from(table).select(select);
                if (orderBy) query = query.order(orderBy, { ascending: false });
                const { data, error } = await query;
                if (error) throw error;
                return data;
             } catch (e: any) { return null; }
          };

          const [pData, vData, oData, cDataRaw] = await Promise.all([
              fetchSafely('products', '*', 'created_at'),
              fetchSafely('vendors'),
              fetchSafely('orders', '*', 'created_at'),
              fetchSafely('couriers')
          ]);

          if (pData) setProducts(pData.map((p: any) => ({ ...p, vendorId: p.vendor_id, contactPhone: p.contact_phone })) as Product[]);
          if (vData) setVendors(vData.map((v: any) => ({ ...v, vendorId: v.vendor_id, storeName: v.store_name, storeDescription: v.store_description, storeAvatarUrl: v.store_avatar_url, userId: v.user_id, isApproved: v.is_approved, contactPhone: v.contact_phone })) as Vendor[]);
          if (oData) setOrders(oData.map((o: any) => ({ ...o, vendorId: o.vendor_id, buyerId: o.buyer_id, courierId: o.courier_id, deliveryFee: o.delivery_fee, deliveryOption: o.delivery_option, createdAt: o.created_at, items: typeof o.items === 'string' ? JSON.parse(o.items) : o.items, locationCoordinates: o.location_coordinates, pickupCoordinates: o.pickup_coordinates })) as Order[]);

          if (cDataRaw) {
              const userIds = [...new Set(cDataRaw.map((d: any) => d.user_id).filter(Boolean))];
              const { data: profiles } = await supabase.from('profiles').select('id, name, email').in('id', userIds);
              const profileMap = new Map<string, any>(profiles?.map((p: any) => [p.id, p]) || []);
              setCouriers(cDataRaw.map((d: any) => ({ ...d, userId: d.user_id, fullName: profileMap.get(d.user_id)?.name || d.full_name || 'Courier', vehicleType: d.vehicle_type, onlineStatus: d.online_status, status: d.status, verified: d.status === 'approved', payoutMethod: d.payout_method })) as Courier[]);
          }

          if (localStorage.getItem('lynqed_role') === 'admin') {
              const uData = await supabase.from('profiles').select('*');
              if (uData.data) setUsers(uData.data as any);
          }
      } catch (e: any) { 
          console.error("Data Fetch Error:", e);
      } finally { 
          setIsDataLoading(false); 
      }
  };

  const login = async (email: string, pass: string) => {
      const { data, error } = await supabase.auth.signInWithPassword({ email, password: pass });
      if (error) return { success: false, error: error.message };
      if (data.user) {
          const user = await fetchUserProfile(data.user.id, data.user);
          if (!user) return { success: false, error: "Profile missing" };
          await fetchData();
          let detRole: Role = 'buyer';
          if (user.roles.includes('admin')) detRole = 'admin';
          else if (user.roles.includes('vendor')) detRole = 'vendor';
          else if (user.roles.includes('courier')) detRole = 'courier';
          return { success: true, role: detRole }; 
      }
      return { success: false };
  };

  const signup = async (email: string, password: string, fullName: string, role: Role, phoneNumber?: string) => {
      const { data, error } = await supabase.auth.signUp({ email, password, options: { data: { full_name: fullName, roles: [role] } } });
      if (error) return { success: false, error: error.message };
      if (data.user) {
           await supabase.from('profiles').insert({ id: data.user.id, email, name: fullName, roles: [role], phone_number: phoneNumber });
           await login(email, password); 
           return { success: true, user: data.user };
      }
      return { success: false };
  };

  const logout = async () => {
      await supabase.auth.signOut();
      localStorage.removeItem('lynqed_role');
      setCurrentUser(null);
      setCurrentRole('guest');
      setCart([]);
      setNotifications([]);
  };

  const resetPassword = async (email: string) => {
      const origin = window.location.origin;
      const { error } = await supabase.auth.resetPasswordForEmail(email, { 
          redirectTo: `${origin}/update-password` 
      });
      if (error) return { success: false, error: error.message };
      return { success: true };
  };

  const updatePassword = async (password: string) => {
      const { error } = await supabase.auth.updateUser({ password });
      if (error) return { success: false, error: error.message };
      return { success: true };
  };

  const switchRole = (role: Role) => { 
      if(currentUser?.roles.includes(role)) {
          setCurrentRole(role); 
          safeSetItem('lynqed_role', role);
          showToast(`Switched to ${role.charAt(0).toUpperCase() + role.slice(1)} Mode`, 'info');
          fetchNotifications(); // Refresh notifications for new role
      }
  };

  const updateProfile = async (data: Partial<User>) => {
      if(!currentUser) return { success: false };
      const updatePayload: any = {};
      if (data.name) updatePayload.name = data.name;
      if (data.avatarUrl) updatePayload.avatar_url = data.avatarUrl;
      if (data.phoneNumber) updatePayload.phone_number = data.phoneNumber;
      if (data.address) updatePayload.address = data.address;
      const { error } = await supabase.from('profiles').update(updatePayload).eq('id', currentUser.id);
      if(!error) {
          showToast("Profile updated", "success");
          fetchUserProfile(currentUser.id);
          return { success: true };
      }
      return { success: false };
  };

  // Notification methods
  const markNotificationAsRead = async (id: string) => {
      await supabase.from('notifications').update({ is_read: true }).eq('id', id);
      setNotifications(prev => prev.map(n => n.id === id ? { ...n, isRead: true } : n));
  };

  const markAllNotificationsRead = async () => {
      if (!currentUser) return;
      await supabase.from('notifications').update({ is_read: true }).eq('user_id', currentUser.id);
      setNotifications(prev => prev.map(n => ({ ...n, isRead: true })));
  };

  const deleteNotification = async (id: string) => {
      await supabase.from('notifications').delete().eq('id', id);
      setNotifications(prev => prev.filter(n => n.id !== id));
  };

  const updateNotificationPreferences = async (prefs: Partial<NotificationPreferences>) => {
      if (!currentUser) return;
      const payload = {
          global_toggle: prefs.globalToggle,
          // Fix: Changed prefs.in_app to prefs.inApp to match interface
          in_app: prefs.inApp,
          email: prefs.email,
          push: prefs.push,
          orders: prefs.orders,
          messages: prefs.messages,
          delivery: prefs.delivery,
          promotions: prefs.promotions,
          system_updates: prefs.systemUpdates
      };
      // remove undefined keys
      Object.keys(payload).forEach(key => (payload as any)[key] === undefined && delete (payload as any)[key]);

      const { error } = await supabase.from('notification_preferences').upsert({ user_id: currentUser.id, ...payload });
      if (!error) {
          showToast("Preferences saved", "success");
          fetchNotificationPreferences(currentUser.id);
      }
  };

  const updateVendorPreferences = async (prefs: Partial<VendorNotificationPreferences>) => {
      if (!currentUser) return;
      const payload = {
          // Fix: Changed snake_case access to camelCase for prefs argument
          new_orders: prefs.newOrders,
          product_approval: prefs.productApproval,
          store_tips: prefs.storeTips,
          policy_changes: prefs.policyChanges
      };
      Object.keys(payload).forEach(key => (payload as any)[key] === undefined && delete (payload as any)[key]);

      const { error } = await supabase.from('vendor_notification_preferences').upsert({ user_id: currentUser.id, ...payload });
      if (!error) {
          showToast("Vendor preferences saved", "success");
          fetchNotificationPreferences(currentUser.id);
      }
  };

  const sendBroadcast = async (title: string, message: string, scope: 'global' | 'role', role?: Role) => {
      const { error } = await supabase.from('notifications').insert({
          target_scope: scope,
          target_role: role,
          type: 'broadcast',
          title,
          message,
          priority: 'normal',
          is_read: false
      });
      if (!error) showToast("Broadcast sent!", "success");
  };

  const submitContactMessage = async (name: string, email: string, message: string) => {
      const { error } = await supabase.from('contact_messages').insert({ name, email, message });
      if(!error) showToast("Message sent!", "success");
      return { success: !error };
  };

  const requestPayout = async (amount: number, method: string) => {
      if(!currentUser) return { success: false };
      const { error } = await supabase.from('payout_requests').insert({ user_id: currentUser.id, amount, method, status: 'pending' });
      if(!error) showToast("Payout requested", "success");
      return { success: !error };
  };

  const uploadFile = async (file: File, folder: string): Promise<string | null> => {
      try {
          const fileName = `${Math.random().toString(36).substring(2)}_${Date.now()}.${file.name.split('.').pop()}`;
          const filePath = `${folder}/${fileName}`;
          const { error: uploadError } = await supabase.storage.from('lynqed-assets').upload(filePath, file);
          if (uploadError) throw uploadError;
          const { data } = supabase.storage.from('lynqed-assets').getPublicUrl(filePath);
          return data.publicUrl;
      } catch (error: any) {
          console.error("Upload Error:", error);
          showToast('Image upload failed', 'error');
          return null;
      }
  };

  const registerVendor = async (data: any): Promise<{ success: boolean }> => {
      if(!currentUser) return { success: false };

      const existingVendor = vendors.find(v => v.userId === currentUser.id);
      const vid = existingVendor?.vendorId || `v-${Date.now()}`;

      const upsertData = { 
          vendor_id: vid, 
          user_id: currentUser.id, 
          store_name: data.storeName, 
          store_description: data.storeDescription, 
          location: data.location, 
          contact_phone: data.contactPhone, 
          store_avatar_url: data.storeAvatarUrl, 
          is_approved: existingVendor ? existingVendor.isApproved : false, 
          rating: existingVendor ? existingVendor.rating : 5.0 
      };

      const { error } = await supabase.from('vendors').upsert(upsertData, { onConflict: 'user_id' });

      if (!error) {
          if (!currentUser.roles.includes('vendor')) {
              const roles = [...new Set([...currentUser.roles, 'vendor' as Role])];
              await supabase.from('profiles').update({ roles }).eq('id', currentUser.id);
          }
          await fetchData(); 
          return { success: true };
      } else {
          console.error("Vendor Upsert Error:", error);
          showToast(`Error: ${error.message || 'Check SQL console for details'}`, "error");
          return { success: false };
      }
  };

  const registerCourier = async (data: any, explicitUserId?: string): Promise<{ success: boolean }> => {
      const uid = explicitUserId || currentUser?.id;
      if(!uid) return { success: false };
      const { error } = await supabase.from('couriers').insert({ 
          user_id: uid, 
          status: 'pending', 
          full_name: data.fullName, 
          vehicle_type: data.vehicle_type, 
          transport_type: data.transport_type, 
          payout_method: data.payout_method, 
          delivery_radius: data.delivery_radius 
      });
      if(!error) { 
          showToast("Application submitted", "success"); 
          fetchData(); 
          return { success: true }; 
      }
      return { success: false };
  };

  const addProduct = async (prod: any) => {
      if(!currentUser) return false;
      const v = vendors.find(v => v.userId === currentUser.id);
      if(!v) return false;
      const { error } = await supabase.from('products').insert({ 
          vendor_id: v.vendorId, 
          title: prod.title, 
          description: prod.description, 
          price: prod.price, 
          category: prod.category, 
          images: prod.images, 
          stock: prod.stock, 
          status: 'pending', 
          location: prod.location, 
          contact_phone: prod.contactPhone 
      });
      if (!error) { showToast("Product submitted", "success"); fetchData(); return true; }
      return false;
  };

  const updateProduct = async (id: string, data: any) => {
      const { error } = await supabase.from('products').update({ ...data, contact_phone: data.contactPhone }).eq('id', id);
      if (!error) { showToast("Product updated", "success"); fetchData(); }
  };

  const deleteProduct = async (id: string) => { await supabase.from('products').delete().eq('id', id); fetchData(); };

  const updateProductStatus = async (id: string, status: string) => { 
      const prod = products.find(p => p.id === id);
      const { error } = await supabase.from('products').update({status}).eq('id', id);
      if (!error && prod) {
           const vendor = vendors.find(v => v.vendorId === prod.vendorId);
           if (vendor) {
                // Send notification to vendor
                await supabase.from('notifications').insert({
                    user_id: vendor.userId,
                    target_scope: 'individual',
                    type: 'product',
                    title: `Product ${status.charAt(0).toUpperCase() + status.slice(1)}`,
                    message: `Your product "${prod.title}" has been ${status}.`,
                    data_payload: { productId: id },
                    priority: 'normal'
                });
           }
           fetchData(); 
      }
  };

  const addToCart = (product: Product, quantity = 1) => {
      setCart(prev => {
          const exists = prev.find(i => i.productId === product.id);
          if (exists) return prev.map(i => i.productId === product.id ? { ...i, quantity: i.quantity + quantity } : i);
          return [...prev, { productId: product.id, quantity, product }];
      });
      showToast("Added to Cart", "success");
  };
  const updateCartQuantity = (pid: string, qty: number) => {
      if(qty <= 0) removeFromCart(pid);
      else setCart(prev => prev.map(i => i.productId === pid ? { ...i, quantity: qty } : i));
  };
  const removeFromCart = (pid: string) => setCart(prev => prev.filter(i => i.productId !== pid));
  const clearCart = () => setCart([]);

  const toggleFavorite = (pid: string) => {
      if (favorites.includes(pid)) {
          setFavorites(prev => prev.filter(i => i !== pid));
          showToast("Removed from Wishlist", "info");
      } else {
          setFavorites(prev => [...prev, pid]);
          showToast("Added to Wishlist", "success");
      }
  };

  const placeOrder = async (option: 'delivery'|'pickup', fee = 0) => {
      if (!currentUser) return;
      const byVendor: any = {};
      cart.forEach(i => { if(!byVendor[i.product.vendorId]) byVendor[i.product.vendorId]=[]; byVendor[i.product.vendorId].push(i); });
      try {
          for(const vid in byVendor) {
              const items = byVendor[vid];
              const subtotal = items.reduce((s:number, i:any) => s + i.product.price * i.quantity, 0);
              const vendor = vendors.find(v => v.vendorId === vid);
              const { data: orderData, error } = await supabase.from('orders').insert({ 
                  buyer_id: currentUser.id, 
                  vendor_id: vid, 
                  items, 
                  total: subtotal+fee, 
                  delivery_fee: fee, 
                  status: 'placed', 
                  delivery_option: option, 
                  pickup_coordinates: vendor ? resolveCoordinates(vendor.location) : undefined, 
                  location_coordinates: resolveCoordinates(currentUser.address || 'campus') 
              }).select().single();

              if (error) throw error;

              // Notify Vendor
              if (vendor) {
                  await supabase.from('notifications').insert({
                      user_id: vendor.userId,
                      target_scope: 'individual',
                      type: 'order',
                      title: 'New Order Received!',
                      message: `You have a new order (#${orderData.id.slice(-4)}) for ₵${subtotal.toFixed(2)}.`,
                      data_payload: { orderId: orderData.id },
                      priority: 'high'
                  });
              }

              for (const item of items) await supabase.from('products').update({ stock: Math.max(0, item.product.stock - item.quantity) }).eq('id', item.productId);
          }
          showToast("Order Placed!", "success"); clearCart(); fetchData();
      } catch (e: any) { showToast("Order failed", "error"); }
  };

  const updateOrderStatus = async (oid: string, status: string) => { 
      const { error } = await supabase.from('orders').update({status}).eq('id', oid);
      if (!error) {
          const order = orders.find(o => o.id === oid);
          if (order) {
              // Notify Buyer
              await supabase.from('notifications').insert({
                  user_id: order.buyerId,
                  target_scope: 'individual',
                  type: 'order',
                  title: 'Order Status Updated',
                  message: `Your order #${oid.slice(-4)} is now ${status.replace('_', ' ')}.`,
                  data_payload: { orderId: oid },
                  priority: 'normal'
              });

              // If ready for delivery, notify couriers
              if (status === 'ready_for_pickup' && order.deliveryOption === 'delivery') {
                  await supabase.from('notifications').insert({
                      target_role: 'courier',
                      target_scope: 'role',
                      type: 'delivery',
                      title: 'New Delivery Available!',
                      message: `An order is ready for delivery near ${order.vendorId.slice(-4)}.`,
                      data_payload: { orderId: oid },
                      priority: 'high'
                  });
              }
          }
          fetchData(); 
      }
  };

  const assignDelivery = async (oid: string) => {
      if (!currentUser) return;
      const { error } = await supabase.from('orders').update({ courier_id: currentUser.id, status: 'courier_assigned' }).eq('id', oid);
      if (!error) { 
          showToast("Job Accepted!", "success"); 
          const order = orders.find(o => o.id === oid);
          if (order) {
              // Notify Buyer
              await supabase.from('notifications').insert({
                  user_id: order.buyerId,
                  target_scope: 'individual',
                  type: 'delivery',
                  title: 'Courier Assigned',
                  message: `A rider has been assigned to your order #${oid.slice(-4)}.`,
                  data_payload: { orderId: oid },
                  priority: 'normal'
              });
          }
          fetchData(); 
      }
  };

  const toggleDriverStatus = async (isOnline: boolean) => {
      if(!currentUser) return;
      const c = couriers.find(d => d.userId === currentUser.id);
      if(c) { await supabase.from('couriers').update({ online_status: isOnline }).eq('id', c.id); fetchData(); }
  };
  const updateDriverLocation = async (lat: number, lng: number) => {
      if(!currentUser) return;
      const c = couriers.find(d => d.userId === currentUser.id);
      if(c) supabase.from('couriers').update({ current_lat: lat, current_lng: lng }).eq('id', c.id).then();
  };

  const banUser = async (uid: string, s: boolean) => { await supabase.from('profiles').update({isBanned: s}).eq('id', uid); fetchData(); };
  const deleteUser = async (uid: string) => { await supabase.from('profiles').delete().eq('id', uid); fetchData(); };

  const approveVendor = async (vid: string, s: boolean) => { 
      const { error } = await supabase.from('vendors').update({ is_approved: s }).eq('vendor_id', vid);
      if (!error) {
          const vendor = vendors.find(v => v.vendorId === vid);
          if (vendor) {
               await supabase.from('notifications').insert({
                   user_id: vendor.userId,
                   target_scope: 'individual',
                   type: 'account',
                   title: s ? 'Store Approved!' : 'Store Verification Revoked',
                   message: s ? 'Congratulations! Your store is now live on the marketplace.' : 'Your store verification has been removed. Please contact admin.',
                   priority: 'high'
               });
          }
          fetchData(); 
      }
  };

  const approveCourier = async (id: string, userId: string, status: string) => { 
      await supabase.from('couriers').update({status}).eq('id', id); 
      if (status === 'approved') {
          const { data: profile } = await supabase.from('profiles').select('roles').eq('id', userId).single();
          if (profile) {
              const roles = [...new Set([...profile.roles, 'courier'])];
              await supabase.from('profiles').update({ roles }).eq('id', userId);
          }
          await supabase.from('notifications').insert({
              user_id: userId,
              target_scope: 'individual',
              type: 'account',
              title: 'Courier Application Approved!',
              message: 'You can now start accepting delivery jobs on campus.',
              priority: 'high'
          });
      }
      fetchData(); 
  };

  const showToast = (message: string, type: 'success' | 'error' | 'info') => setToast({ message, type });
  const hideToast = () => setToast(null);
  const requestNotificationPermission = async () => { return true; };

  const refreshData = async () => {
    setIsDataLoading(true);
    await fetchData();
    await fetchNotifications();
    setIsDataLoading(false);
  };

  return (
    <AppContext.Provider value={{
      currentUser, currentRole, products, vendors, orders, cart, couriers, users, 
      notifications, unreadNotificationCount, notificationPreferences, vendorPreferences,
      isLoading, isDataLoading, connectionError, favorites, toast, theme,
      login, signup, logout, resetPassword, updatePassword, switchRole, updateTheme,
      updateProfile, submitContactMessage, requestPayout,
      uploadFile, registerCourier, registerVendor, refreshData,
      addProduct, updateProduct, updateProductStatus, deleteProduct,
      addToCart, updateCartQuantity, removeFromCart, clearCart, placeOrder, updateOrderStatus, assignDelivery, toggleFavorite,
      markNotificationAsRead, markAllNotificationsRead, deleteNotification, updateNotificationPreferences, updateVendorPreferences, sendBroadcast,
      banUser, deleteUser, approveVendor, approveCourier,
      toggleDriverStatus, updateDriverLocation,
      showToast, hideToast, requestNotificationPermission
    }}>
      {children}
    </AppContext.Provider>
  );
};

export const useApp = () => {
  const context = useContext(AppContext);
  if (context === undefined) {
    throw new Error('useApp must be used within an AppProvider');
  }
  return context;
};

import React, { useEffect, useState, useRef } from 'react';

// --- Avatar ---
interface AvatarProps {
  src?: string | null;
  name: string;
  size?: 'sm' | 'md' | 'lg' | 'xl' | '2xl';
  className?: string;
  onClick?: () => void;
}

export const Avatar: React.FC<AvatarProps> = ({ src, name, size = 'md', className = '', onClick }) => {
  const [imgError, setImgError] = useState(false);

  useEffect(() => {
    setImgError(false);
  }, [src]);

  const initials = name
    ? name.split(' ').slice(0, 2).map(n => n[0]).join('').toUpperCase()
    : '?';

  const sizeClasses = {
    sm: "w-8 h-8 text-[10px]",
    md: "w-10 h-10 text-xs",
    lg: "w-14 h-14 text-sm",
    xl: "w-24 h-24 text-xl",
    '2xl': "w-32 h-32 text-3xl"
  };

  const colors = [
    'bg-blue-100 text-blue-600 dark:bg-blue-900/40 dark:text-blue-400',
    'bg-green-100 text-green-600 dark:bg-green-900/40 dark:text-green-400',
    'bg-yellow-100 text-yellow-600 dark:bg-yellow-900/40 dark:text-yellow-400',
    'bg-purple-100 text-purple-600 dark:bg-purple-900/40 dark:text-purple-400',
    'bg-pink-100 text-pink-600 dark:bg-pink-900/40 dark:text-pink-400',
    'bg-indigo-100 text-indigo-600 dark:bg-indigo-900/40 dark:text-indigo-400',
  ];
  const colorIndex = name.length % colors.length;
  const colorClass = colors[colorIndex];

  const baseClasses = `rounded-full flex items-center justify-center font-bold object-cover shadow-sm border border-white dark:border-gray-800 flex-shrink-0 ${sizeClasses[size]} ${className}`;

  if (src && !imgError) {
    return (
      <img 
        src={src} 
        alt={name} 
        className={`${baseClasses} bg-gray-100 dark:bg-gray-800`}
        onError={() => setImgError(true)}
        onClick={onClick}
      />
    );
  }

  return (
    <div className={`${baseClasses} ${colorClass}`} onClick={onClick} title={name}>
      {initials}
    </div>
  );
};

// --- Button ---
interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'outline' | 'ghost' | 'danger' | 'success';
  fullWidth?: boolean;
  size?: 'sm' | 'md' | 'lg';
  icon?: string;
}

export const Button: React.FC<ButtonProps> = ({ 
  children, variant = 'primary', fullWidth, size = 'md', icon, className = '', ...props 
}) => {
  const base = "inline-flex items-center justify-center rounded-2xl font-semibold transition-all duration-300 active:scale-[0.96] disabled:opacity-50 disabled:active:scale-100 tracking-tight";

  const variants = {
    primary: "bg-gradient-to-r from-primary to-primaryDark text-white hover:shadow-glow shadow-lg shadow-primary/30 border border-transparent",
    secondary: "bg-white dark:bg-darkSurface text-gray-800 dark:text-white border border-gray-100 dark:border-gray-800 hover:bg-gray-50 dark:hover:bg-gray-800 shadow-sm",
    outline: "border-2 border-primary/20 text-primary dark:text-primaryLight bg-transparent hover:bg-primary/5",
    ghost: "bg-transparent text-gray-500 dark:text-gray-400 hover:bg-gray-100/50 dark:hover:bg-gray-800/50 hover:text-gray-900 dark:hover:text-white shadow-none",
    danger: "bg-red-50 dark:bg-red-900/20 text-red-600 dark:text-red-400 hover:bg-red-100 border border-red-100 dark:border-red-900/30",
    success: "bg-green-500 text-white hover:bg-green-600 shadow-lg shadow-green-500/30 border border-transparent"
  };

  const sizes = {
    sm: "px-3 py-1.5 text-xs",
    md: "px-5 py-3 text-sm",
    lg: "px-8 py-4 text-base"
  };

  return (
    <button 
      className={`${base} ${variants[variant]} ${sizes[size]} ${fullWidth ? 'w-full' : ''} ${className}`}
      {...props}
    >
      {icon && <i className={`fa-solid fa-${icon} mr-2.5 ${size === 'sm' ? 'text-xs' : 'text-sm'}`}></i>}
      {children}
    </button>
  );
};

