// --- Toast Notification ---
export interface ToastMessage {
    message: string;
    type: 'success' | 'error' | 'info';
}

export const Toast: React.FC<{ toast: ToastMessage | null; onClose: () => void }> = ({ toast, onClose }) => {
    const [visible, setVisible] = useState(false);
    const [currentToast, setCurrentToast] = useState<ToastMessage | null>(null);
    const mainTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
    const exitTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

    useEffect(() => {
        if (toast) {
            // New toast arriving
            if (mainTimerRef.current) clearTimeout(mainTimerRef.current);
            if (exitTimerRef.current) clearTimeout(exitTimerRef.current);

            setCurrentToast(toast);
            setVisible(true);

            mainTimerRef.current = setTimeout(() => {
                setVisible(false);
                exitTimerRef.current = setTimeout(() => {
                    onClose();
                }, 400); // Wait for exit animation
            }, 3000);
        }
    }, [toast, onClose]);

    if (!currentToast && !visible) return null;

    const icons = {
        success: 'circle-check',
        error: 'circle-exclamation',
        info: 'circle-info'
    };

    const colors = {
        success: 'bg-gray-900 dark:bg-primary text-white',
        error: 'bg-red-500 text-white',
        info: 'bg-blue-500 text-white'
    };

    return (
        <div 
          className={`fixed top-6 left-1/2 transform -translate-x-1/2 z-[100] transition-all duration-500 ease-in-out cursor-pointer ${visible ? 'translate-y-0 opacity-100' : '-translate-y-12 opacity-0 pointer-events-none'}`}
          onClick={() => { setVisible(false); onClose(); }}
        >
            <div className={`flex items-center gap-3 px-6 py-3 rounded-full shadow-2xl ${colors[currentToast?.type || 'info']} min-w-[200px] max-w-xs border border-white/10`}>
                <i className={`fa-solid fa-${icons[currentToast?.type || 'info']}`}></i>
                <span className="text-sm font-bold tracking-wide">{currentToast?.message}</span>
            </div>
        </div>
    );
};

