// --- Toast Notification ---
export interface ToastMessage {
    message: string;
    type: 'success' | 'error' | 'info';
}

export const Toast: React.FC<{ toast: ToastMessage | null; onClose: () => void }> = ({ toast, onClose }) => {
    const [visible, setVisible] = useState(false);

    useEffect(() => {
        if (toast) {
            setVisible(true);
            const timer = setTimeout(() => {
                setVisible(false);
                setTimeout(onClose, 300); // Wait for animation
            }, 3000);
            return () => clearTimeout(timer);
        }
    }, [toast, onClose]);

    if (!toast) return null;

    const icons = {
        success: 'circle-check',
        error: 'circle-exclamation',
        info: 'circle-info'
    };

    const colors = {
        success: 'bg-gray-900 dark:bg-primary text-white',
        error: 'bg-red-500 text-white',
        info: 'bg-blue-500 text-white'
    };

    return (
        <div className={`fixed top-6 left-1/2 transform -translate-x-1/2 z-[100] transition-all duration-500 ease-in-out ${visible ? 'translate-y-0 opacity-100' : '-translate-y-8 opacity-0'}`}>
            <div className={`flex items-center gap-3 px-6 py-3 rounded-full shadow-2xl ${colors[toast.type]} min-w-[200px] max-w-xs`}>
                <i className={`fa-solid fa-${icons[toast.type]}`}></i>
                <span className="text-sm font-bold tracking-wide text-center">{toast.message}</span>
            </div>
        </div>
    );
};

// --- Share Modal ---
interface ShareModalProps {
    isOpen: boolean;
    onClose: () => void;
    title: string;
    text: string;
    url: string;
}

export const ShareModal: React.FC<ShareModalProps> = ({ isOpen, onClose, title, text, url }) => {
    const [copied, setCopied] = useState(false);

    if (!isOpen) return null;

    // Fix for sandboxed environments where origin might be 'blob:'
    const cleanUrl = url.startsWith('blob:') 
        ? `https://lynqed.vercel.app${window.location.hash}`
        : url;

    const encodedUrl = encodeURIComponent(cleanUrl);
    const encodedText = encodeURIComponent(text);

    const shareOptions = [
        {
            name: 'WhatsApp',
            icon: 'fa-brands fa-whatsapp',
            color: 'bg-[#25D366]',
            link: `https://wa.me/?text=${encodedText}%20${encodedUrl}`
        },
        {
            name: 'Telegram',
            icon: 'fa-brands fa-telegram',
            color: 'bg-[#0088cc]',
            link: `https://t.me/share/url?url=${encodedUrl}&text=${encodedText}`
        },
        {
            name: 'X (Twitter)',
            icon: 'fa-brands fa-x-twitter',
            color: 'bg-black',
            link: `https://twitter.com/intent/tweet?text=${encodedText}&url=${encodedUrl}`
        },
        {
            name: 'Facebook',
            icon: 'fa-brands fa-facebook-f',
            color: 'bg-[#1877F2]',
            link: `https://www.facebook.com/sharer/sharer.php?u=${encodedUrl}`
        },
        {
            name: 'LinkedIn',
            icon: 'fa-brands fa-linkedin-in',
            color: 'bg-[#0077b5]',
            link: `https://www.linkedin.com/sharing/share-offsite/?url=${encodedUrl}`
        },
        {
            name: 'Reddit',
            icon: 'fa-brands fa-reddit-alien',
            color: 'bg-[#FF4500]',
            link: `https://www.reddit.com/submit?url=${encodedUrl}&title=${encodedText}`
        },
        {
            name: 'Email',
            icon: 'fa-solid fa-envelope',
            color: 'bg-gray-600',
            link: `mailto:?subject=${encodeURIComponent(title)}&body=${encodedText}%20${encodedUrl}`
        }
    ];

    const copyToClipboard = async () => {
        try {
            await navigator.clipboard.writeText(cleanUrl);
            setCopied(true);
            setTimeout(() => setCopied(false), 2000);
        } catch (err) {
            console.error('Failed to copy', err);
        }
    };

    return (
        <div className="fixed inset-0 z-[110] flex items-end sm:items-center justify-center bg-black/60 backdrop-blur-sm animate-fade-in p-0 sm:p-4">
            <div className="absolute inset-0" onClick={onClose}></div>
            <Card className="w-full max-w-md rounded-t-[2.5rem] sm:rounded-[2.5rem] animate-slide-up relative z-10 p-8 flex flex-col max-h-[90vh]">
                <div className="flex justify-between items-start mb-8 flex-shrink-0">
                    <div>
                        <h3 className="text-2xl font-display font-black dark:text-white">Share Store</h3>
                        <p className="text-xs text-gray-400 font-bold uppercase tracking-widest mt-1">Spread the word on campus</p>
                    </div>
                    <button onClick={onClose} className="w-10 h-10 rounded-full bg-gray-50 dark:bg-gray-800 flex items-center justify-center text-gray-400 hover:text-gray-600 dark:hover:text-gray-200 transition-colors">
                        <i className="fa-solid fa-xmark"></i>
                    </button>
                </div>

                <div className="grid grid-cols-4 gap-6 mb-10 overflow-y-auto hide-scrollbar py-2">
                    {shareOptions.map((opt) => (
                        <a 
                            key={opt.name}
                            href={opt.link}
                            target="_blank"
                            rel="noopener noreferrer"
                            className="flex flex-col items-center gap-2 group"
                        >
                            <div className={`w-14 h-14 rounded-2xl ${opt.color} text-white flex items-center justify-center shadow-lg group-active:scale-90 transition-all group-hover:-translate-y-1`}>
                                <i className={`${opt.icon} text-2xl`}></i>
                            </div>
                            <span className="text-[9px] font-black text-gray-400 dark:text-gray-500 uppercase tracking-tighter text-center group-hover:text-primary transition-colors">{opt.name}</span>
                        </a>
                    ))}
                </div>

                <div className="space-y-4 flex-shrink-0">
                    <p className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] ml-1">Unique Store Link</p>
                    <div className="flex items-center bg-gray-50 dark:bg-darkBg rounded-2xl p-2 pl-4 border border-gray-100 dark:border-gray-800 shadow-inner">
                        <span className="flex-1 truncate text-xs text-gray-500 dark:text-gray-400 font-medium mr-2">{cleanUrl}</span>
                        <Button 
                            size="sm" 
                            variant={copied ? 'success' : 'primary'} 
                            onClick={copyToClipboard}
                            className="h-11 px-6 min-w-[100px]"
                        >
                            {copied ? 'Copied!' : 'Copy'}
                        </Button>
                    </div>
                </div>
            </Card>
        </div>
    );
};

import React, { useEffect } from 'react';
import { HashRouter as Router, Routes, Route, Navigate, useNavigate } from 'react-router-dom';
import { AppProvider, useApp } from './context';
import { Layout } from './components/Layout';
import { Welcome, BuyerDashboard } from './pages/Home';
import { SearchPage } from './pages/Search';
import { ProductDetail, Cart, Checkout, StorePage } from './pages/Product';
import { VendorDashboard, VendorProducts, AddProduct, EditProduct, VendorOrders, VendorOnboarding } from './pages/Vendor';
import { AdminDashboard } from './pages/Admin';
import { UserProfile, OrdersPage, WishlistPage } from './pages/Profile';
import { Login, Register, AdminLogin, ForgotPassword, UpdatePassword } from './pages/Auth';
import { DeliveryDashboard } from './pages/Delivery';
import { AboutPage } from './pages/About';
import { PrivacyPage } from './pages/Privacy';
import { TermsPage } from './pages/Terms';
import { FAQPage } from './pages/FAQ';
import { supabase } from './supabaseClient';
import { ConnectionErrorOverlay } from './components/UI';

const ProtectedRoute: React.FC<{ children: React.ReactNode; role?: string }> = ({ children, role }) => {
    const { currentUser, currentRole, isLoading } = useApp();

    if (isLoading) {
        return (
            <div className="min-h-screen flex flex-col items-center justify-center bg-gray-50 dark:bg-darkBg">
                <div className="animate-spin rounded-full h-8 w-8 border-2 border-primary border-b-transparent mb-4"></div>
                <p className="text-xs font-bold text-gray-400 uppercase tracking-widest animate-pulse">Syncing Session...</p>
            </div>
        );
    }

    if (!currentUser) return <Navigate to="/login" replace />;

    if (role && currentRole !== 'admin') {
        if (!currentUser.roles.includes(role as any)) {
            return <Navigate to="/" replace />;
        }
        if (currentRole !== role) {
            return <Navigate to="/" replace />;
        }
    }

    return <>{children}</>;
};

const AuthEventHandler = () => {
    const navigate = useNavigate();

    useEffect(() => {
        // Handle explicit Supabase Auth events
        const { data: { subscription } } = supabase.auth.onAuthStateChange((event) => {
            if (event === 'PASSWORD_RECOVERY') {
                navigate('/update-password');
            }
        });

        // Robust manual detection for recovery links
        const checkRecovery = () => {
            const hashParams = new URLSearchParams(window.location.hash.split('?')[1] || '');
            const searchParams = new URLSearchParams(window.location.search);

            if (hashParams.get('type') === 'recovery' || searchParams.get('type') === 'recovery') {
                navigate('/update-password');
            }
        };

        checkRecovery();

        return () => {
            subscription.unsubscribe();
        };
    }, [navigate]);

    return null;
}

const AppContent = () => {
  const { connectionError, refreshData } = useApp();

  return (
    <Layout>
      <AuthEventHandler />
      {connectionError && <ConnectionErrorOverlay onRetry={refreshData} />}
      <Routes>
        <Route path="/" element={<Welcome />} />
        <Route path="/login" element={<Login />} />
        <Route path="/register" element={<Register />} />
        <Route path="/forgot-password" element={<ForgotPassword />} />
        <Route path="/update-password" element={<UpdatePassword />} />

        <Route path="/store/:vendorId" element={<StorePage />} />
        <Route path="/about" element={<AboutPage />} />
        <Route path="/privacy" element={<PrivacyPage />} />
        <Route path="/terms" element={<TermsPage />} />
        <Route path="/faq" element={<FAQPage />} />

        <Route path="/secret-access" element={<AdminLogin />} />

        <Route path="/buyer/dashboard" element={<ProtectedRoute role="buyer"><BuyerDashboard /></ProtectedRoute>} />
        <Route path="/buyer/search" element={<ProtectedRoute><SearchPage /></ProtectedRoute>} />
        <Route path="/buyer/product/:id" element={<ProtectedRoute><ProductDetail /></ProtectedRoute>} />
        <Route path="/buyer/cart" element={<ProtectedRoute><Cart /></ProtectedRoute>} />
        <Route path="/buyer/checkout" element={<ProtectedRoute><Checkout /></ProtectedRoute>} />
        <Route path="/buyer/orders" element={<ProtectedRoute role="buyer"><OrdersPage /></ProtectedRoute>} />
        <Route path="/buyer/wishlist" element={<ProtectedRoute role="buyer"><WishlistPage /></ProtectedRoute>} />
        <Route path="/buyer/profile" element={<ProtectedRoute><UserProfile /></ProtectedRoute>} />

        <Route path="/vendor/onboarding" element={<ProtectedRoute><VendorOnboarding /></ProtectedRoute>} />
        <Route path="/vendor/dashboard" element={<ProtectedRoute role="vendor"><VendorDashboard /></ProtectedRoute>} />
        <Route path="/vendor/products" element={<ProtectedRoute role="vendor"><VendorProducts /></ProtectedRoute>} />
        <Route path="/vendor/products/new" element={<ProtectedRoute role="vendor"><AddProduct /></ProtectedRoute>} />
        <Route path="/vendor/products/:id/edit" element={<ProtectedRoute role="vendor"><EditProduct /></ProtectedRoute>} />
        <Route path="/vendor/orders" element={<ProtectedRoute role="vendor"><VendorOrders /></ProtectedRoute>} />
        <Route path="/vendor/profile" element={<ProtectedRoute role="vendor"><UserProfile /></ProtectedRoute>} />

        <Route path="/delivery/dashboard" element={<ProtectedRoute role="courier"><DeliveryDashboard /></ProtectedRoute>} />

        <Route path="/admin/dashboard" element={<ProtectedRoute role="admin"><AdminDashboard /></ProtectedRoute>} />
      </Routes>
    </Layout>
  );
}

const App: React.FC = () => {
  return (
    <AppProvider>
      <Router>
         <AppContent />
      </Router>
    </AppProvider>
  );
};

export default App;
